import argparse

from taf.ul.bts_kpi_report_generator import bts_kpi_report_generator

parser_generate = argparse.ArgumentParser(description='Parameters: generation_kpi_report')
parser_generate.add_argument('-p', '--path_dir', dest='path_dir', type=str, required=True,
                             help='path catalog with files: PM, HASH, XML')
parser_generate.add_argument('-f', '--source_kpi', dest='source_kpi', type=str, required=True,
                             help='release version with KPIs, (e.g LTE19A), but maybe put "latest" and will choose latest or path file YAML with own'
                                  'release')
parser_generate.add_argument('-k', '--kpi_to_generate', dest='kpi_to_generate', type=str, default='all',
                             help='path file YAML with list chose KPIs or Python dict')
parser_generate.add_argument('-t', '--type', dest='kpi_type', type=str, default=None, help='type kpi: LTE or 5G')
parser_generate.add_argument('-b', '--build', dest='build', type=str, default='NA', help='version build, default "NA"')
parser_generate.add_argument('-g', '--generate_html_xlsx', dest='generate_html_xlsx', action='store_true', default=False,
                             help='generate HTML and XLSX files with counters')
parser_generate.add_argument('-j', '--generate_json', dest='generate_json', action='store_true', default=False,
                             help='generate JSON files with results')
parser_generate.add_argument('-s', '--start_skip', dest='number_of_start_intervals_to_skip', type=int, default=0,
                             help='start skip measurement, default 0')
parser_generate.add_argument('-e', '--end_skip', dest='number_of_end_intervals_to_skip', type=int, default=0,
                             help='end skip measurement, default 0')
parser_generate.add_argument('-n', '--report_name', dest='report_name', type=str, default='KPI_Report',
                             help='name for file XLSX with report, default KPI_Report')


def generate_kpi_report():
    arguments = parser_generate.parse_args()
    bts_kpi_report_generator.generate_kpi_report(arguments.path_dir, arguments.source_kpi, arguments.kpi_to_generate, arguments.kpi_type,
                                                 arguments.build, arguments.generate_html_xlsx, arguments.generate_json,
                                                 arguments.number_of_start_intervals_to_skip, arguments.number_of_end_intervals_to_skip,
                                                 arguments.report_name)
